#[inline]
unsafe extern "C-unwind" fn set_offsets_for_motion_search(
    cpi: *const AV1_COMP,
    x: *mut MACROBLOCK,
    mut mi_row: core::ffi::c_int,
    mut mi_col: core::ffi::c_int,
    mut bsize: BLOCK_SIZE,
) {
    let cm: *const AV1_COMMON = &(*cpi).common;
    let mi_params: *const CommonModeInfoParams = &(*cm).mi_params;
    let num_planes: core::ffi::c_int = av1_num_planes(cm) as core::ffi::c_int;
    let xd: *mut MACROBLOCKD = &raw mut (*x).e_mbd;
    let mi_width: core::ffi::c_int = mi_size_wide[bsize as usize] as core::ffi::c_int;
    let mi_height: core::ffi::c_int = mi_size_high[bsize as usize] as core::ffi::c_int;
    set_mode_info_offsets(
        &(*cpi).common.mi_params,
        &(*cpi).mbmi_ext_info,
        x,
        xd,
        mi_row,
        mi_col,
    );
    av1_setup_dst_planes(
        ((*xd).plane).as_mut_ptr(),
        bsize,
        &raw mut (*(*cm).cur_frame).buf,
        mi_row,
        mi_col,
        0 as core::ffi::c_int,
        num_planes,
    );
    av1_set_mv_limits(
        mi_params,
        &raw mut (*x).mv_limits,
        mi_row,
        mi_col,
        mi_height,
        mi_width,
        (*cpi).oxcf.border_in_pixels,
    );
    set_plane_n4(xd, mi_width, mi_height, num_planes);
    (*xd).mi_row = mi_row;
    (*xd).mi_col = mi_col;
    (*xd).mb_to_top_edge = -(mi_row * ((1 as core::ffi::c_int) << 2 as core::ffi::c_int)
        * 8 as core::ffi::c_int);
    (*xd).mb_to_bottom_edge = ((*mi_params).mi_rows - mi_height - mi_row)
        * ((1 as core::ffi::c_int) << 2 as core::ffi::c_int) * 8 as core::ffi::c_int;
    (*xd).mb_to_left_edge = -(mi_col * ((1 as core::ffi::c_int) << 2 as core::ffi::c_int)
        * 8 as core::ffi::c_int);
    (*xd).mb_to_right_edge = ((*mi_params).mi_cols - mi_width - mi_col)
        * ((1 as core::ffi::c_int) << 2 as core::ffi::c_int) * 8 as core::ffi::c_int;
    av1_setup_src_planes(
        x as *mut macroblock,
        (*cpi).source,
        mi_row,
        mi_col,
        num_planes,
        bsize,
    );
}
#[inline]
unsafe extern "C-unwind" fn convert_bsize_to_idx(mut bsize: BLOCK_SIZE) -> core::ffi::c_int {
    match bsize as core::ffi::c_int {
        15 => return 0 as core::ffi::c_int,
        12 => return 1 as core::ffi::c_int,
        9 => return 2 as core::ffi::c_int,
        6 => return 3 as core::ffi::c_int,
        3 => return 4 as core::ffi::c_int,
        _ => return -(1 as core::ffi::c_int),
    };
}
unsafe extern "C-unwind" fn get_feature_file_name(
    mut id: core::ffi::c_int,
) -> *mut core::ffi::c_char {
    static mut feature_file_names: [*mut core::ffi::c_char; 8] = [
        b"feature_before_partition_none\0" as *const u8 as *const core::ffi::c_char
            as *mut core::ffi::c_char,
        b"feature_before_partition_none_prune_rect\0" as *const u8
            as *const core::ffi::c_char as *mut core::ffi::c_char,
        b"feature_after_partition_none_prune\0" as *const u8 as *const core::ffi::c_char
            as *mut core::ffi::c_char,
        b"feature_after_partition_none_terminate\0" as *const u8
            as *const core::ffi::c_char as *mut core::ffi::c_char,
        b"feature_after_partition_split_terminate\0" as *const u8
            as *const core::ffi::c_char as *mut core::ffi::c_char,
        b"feature_after_partition_split_prune_rect\0" as *const u8
            as *const core::ffi::c_char as *mut core::ffi::c_char,
        b"feature_after_partition_rect\0" as *const u8 as *const core::ffi::c_char
            as *mut core::ffi::c_char,
        b"feature_after_partition_ab\0" as *const u8 as *const core::ffi::c_char
            as *mut core::ffi::c_char,
    ];
    return feature_file_names[id as usize];
}
unsafe extern "C-unwind" fn write_features_to_file(
    path: *const core::ffi::c_char,
    is_test_mode: bool,
    mut features: *const core::ffi::c_float,
    feature_size: core::ffi::c_int,
    id: core::ffi::c_int,
    bsize: BLOCK_SIZE,
    mi_row: core::ffi::c_int,
    mi_col: core::ffi::c_int,
) {
    if WRITE_FEATURE_TO_FILE == 0 && !is_test_mode {
        return;
    }
    let mut filename: [core::ffi::c_char; 256] = [0; 256];
    snprintf(
        filename.as_mut_ptr(),
        ::core::mem::size_of::<[core::ffi::c_char; 256]>() as size_t,
        b"%s/%s\0" as *const u8 as *const core::ffi::c_char,
        path,
        get_feature_file_name(id),
    );
    let mut pfile: *mut FILE = fopen(
        filename.as_mut_ptr(),
        b"a\0" as *const u8 as *const core::ffi::c_char,
    ) as *mut FILE;
    if pfile.is_null() {
        return;
    }
    if !is_test_mode {
        fprintf(
            pfile,
            b"%d,%d,%d,%d,%d\n\0" as *const u8 as *const core::ffi::c_char,
            id,
            bsize as core::ffi::c_int,
            mi_row,
            mi_col,
            feature_size,
        );
    }
    let mut i: core::ffi::c_int = 0 as core::ffi::c_int;
    while i < feature_size {
        fprintf(
            pfile,
            b"%.6f\0" as *const u8 as *const core::ffi::c_char,
            *features.offset(i as isize) as core::ffi::c_double,
        );
        if i < feature_size - 1 as core::ffi::c_int {
            fprintf(pfile, b",\0" as *const u8 as *const core::ffi::c_char);
        }
        i += 1;
    }
    fprintf(pfile, b"\n\0" as *const u8 as *const core::ffi::c_char);
    fclose(pfile);
}
