#[inline]
unsafe extern "C-unwind" fn get_min_bsize(
    mut sms_tree: *const SIMPLE_MOTION_DATA_TREE,
    mut min_bw: *mut core::ffi::c_int,
    mut min_bh: *mut core::ffi::c_int,
) {
    if sms_tree.is_null() {
        return;
    }
    let bsize: BLOCK_SIZE = (*sms_tree).block_size;
    if bsize as core::ffi::c_int == BLOCK_4X4 as core::ffi::c_int {
        *min_bw = 0 as core::ffi::c_int;
        *min_bh = 0 as core::ffi::c_int;
        return;
    }
    let mut part_type: PARTITION_TYPE = (*sms_tree).partitioning;
    if part_type as core::ffi::c_int == PARTITION_INVALID as core::ffi::c_int {
        return;
    }
    if part_type as core::ffi::c_int == PARTITION_SPLIT as core::ffi::c_int {
        let mut i: core::ffi::c_int = 0 as core::ffi::c_int;
        while i < SUB_PARTITIONS_SPLIT {
            get_min_bsize((*sms_tree).split[i as usize], min_bw, min_bh);
            i += 1;
        }
    } else {
        if part_type as core::ffi::c_int == PARTITION_HORZ_A as core::ffi::c_int
            || part_type as core::ffi::c_int == PARTITION_HORZ_B as core::ffi::c_int
            || part_type as core::ffi::c_int == PARTITION_VERT_A as core::ffi::c_int
            || part_type as core::ffi::c_int == PARTITION_VERT_B as core::ffi::c_int
        {
            part_type = PARTITION_SPLIT as core::ffi::c_int as PARTITION_TYPE;
        }
        let subsize: BLOCK_SIZE = get_partition_subsize(bsize, part_type) as BLOCK_SIZE;
        if subsize as core::ffi::c_int != BLOCK_INVALID as core::ffi::c_int {
            *min_bw = if *min_bw
                < mi_size_wide_log2[subsize as usize] as core::ffi::c_int
            {
                *min_bw
            } else {
                mi_size_wide_log2[subsize as usize] as core::ffi::c_int
            };
            *min_bh = if *min_bh
                < mi_size_high_log2[subsize as usize] as core::ffi::c_int
            {
                *min_bh
            } else {
                mi_size_high_log2[subsize as usize] as core::ffi::c_int
            };
        }
    };
}
